import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv, texture, positionLocal, vec3, vec4, mix, float, uniform, mul, add,
  smoothstep, dot, vec2, clamp, sub, oneMinus, luminance
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, DirectionalGroup } = ctx.THREE;
  const THREE = ctx.THREE;

  const group = new Group();
  group.name = config?.id || 'photo-hero-composite';

  const colors = config?.intent?.visualSpec?.colors || {
    background: '#0b0b10', surface: '#16161d', ink: '#16161d',
    paper: '#e8ecf2', accent: '#ff2a38'
  };

  const timelines = [];
  const primitiveHandles = [];
  const disposables = [];

  // ---------------------------------------------------------------
  // BACKDROP STAGE (vertical gradient plane, never a flat void)
  // ---------------------------------------------------------------
  const bgTop = new Color('#16161d');
  const bgBot = new Color('#0b0b10');
  const backdropGeo = new PlaneGeometry(7, 6, 1, 1);
  const backdropMat = new MeshBasicNodeMaterial();
  {
    const vy = uv().y;
    const grad = mix(vec3(bgBot.r, bgBot.g, bgBot.b), vec3(bgTop.r, bgTop.g, bgTop.b), smoothstep(0.0, 1.0, vy));
    backdropMat.colorNode = grad;
  }
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);
  disposables.push(backdropGeo, backdropMat);

  // ---------------------------------------------------------------
  // NODE-LOCAL RIM / ACCENT LIGHTS
  // ---------------------------------------------------------------
  const rim = new THREE.DirectionalLight(new Color(colors.accent), 0.9);
  rim.position.set(-3, 1.5, 2);
  group.add(rim);
  const fill = new THREE.DirectionalLight(new Color('#e8ecf2'), 0.5);
  fill.position.set(3, 2, 3);
  group.add(fill);

  // ---------------------------------------------------------------
  // PARALLAX PHOTO PLATE (displacement + filmic grade in TSL)
  // ---------------------------------------------------------------
  const plateW = 4.0, plateH = 2.5;
  const plateGeo = new PlaneGeometry(plateW, plateH, 64, 64);
  const plateMat = new MeshStandardNodeMaterial();
  plateMat.roughness = 0.6;
  plateMat.metalness = 0.1;
  plateMat.transparent = true;
  plateMat.side = DoubleSide;

  const uOpacity = uniform(0.0);
  const uParallax = uniform(0.0);
  const uDepthAmp = uniform(0.18);
  const uHasTex = uniform(0.0);

  // color placeholders (surface tone until textures load)
  const baseTone = new Color(colors.surface);

  plateMat.opacityNode = uOpacity;

  const plateMesh = new Mesh(plateGeo, plateMat);
  plateMesh.position.set(0, 0, 0);
  group.add(plateMesh);
  disposables.push(plateGeo, plateMat);

  // Load textures then wire displacement + grade
  ctx.textureLoader.loadTexture(config.imageUrl).then((colorTex) => {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      uHasTex.value = 1.0;

      const suv = uv();
      // parallax UV offset driven by depth
      const depthSample = texture(depthTex, suv).r;
      const parallaxUv = add(suv, mul(vec2(uParallax, mul(uParallax, float(0.5))), sub(depthSample, float(0.5))));

      const colSample = texture(colorTex, parallaxUv);

      // --- Filmic grade in TSL ---
      // blacks lifted to #0d0d12, highlights shouldered toward paper,
      // midtone contrast +12%, desat -8% preserving red channel.
      const rgb = colSample.rgb;
      const blackFloor = vec3(0.051, 0.051, 0.070); // #0d0d12
      const lifted = mix(blackFloor, vec3(1.0, 1.0, 1.0), rgb);
      // midtone contrast
      const contrasted = add(mul(sub(lifted, float(0.5)), float(1.12)), float(0.5));
      const cl = clamp(contrasted, float(0.0), float(1.0));
      // desaturation -8% but preserve red
      const lum = luminance(cl);
      const desat = mix(vec3(lum, lum, lum), cl, float(0.92));
      const graded = vec3(cl.r, desat.g, desat.b); // preserve red channel

      // rim key light along silhouette from depth gradient (subtle)
      const rimGlow = mul(smoothstep(float(0.4), float(0.6), depthSample), float(0.06));
      const finalCol = add(graded, mul(vec3(1.0, 1.0, 1.0), rimGlow));

      plateMat.colorNode = finalCol;

      // --- Depth displacement of vertices ---
      const dispSample = texture(depthTex, suv).r;
      const disp = mul(sub(dispSample, float(0.5)), uDepthAmp);
      plateMat.positionNode = add(positionLocal, vec3(0.0, 0.0, disp));

      plateMat.needsUpdate = true;
    });
  });

  // ---------------------------------------------------------------
  // BOTTOM SCRIM GRADIENT (seats caption)  #0b0b1000 -> #0b0b10eb
  // ---------------------------------------------------------------
  const scrimGeo = new PlaneGeometry(plateW, plateH * 0.6, 1, 1);
  const scrimMat = new MeshBasicNodeMaterial();
  scrimMat.transparent = true;
  {
    const vy = uv().y;
    const scrimCol = new Color('#0b0b10');
    scrimMat.colorNode = vec3(scrimCol.r, scrimCol.g, scrimCol.b);
    // opacity 0 at top -> 0.92 at bottom
    scrimMat.opacityNode = mul(oneMinus(smoothstep(float(0.0), float(0.75), vy)), float(0.92));
  }
  const scrim = new Mesh(scrimGeo, scrimMat);
  scrim.position.set(0, -plateH * 0.2, 0.02);
  group.add(scrim);
  disposables.push(scrimGeo, scrimMat);

  // ---------------------------------------------------------------
  // TEXT / CAPTION BLOCK (bottom-left, 0.5 unit padding)
  // ---------------------------------------------------------------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const roleText = {};
  for (const item of items) {
    if (item && item.role && item.text) roleText[item.role] = item.text;
  }
  const kickerStr = roleText.kicker || 'NOVA ATELIER / GENEVA';
  const headlineStr = roleText.headline || 'Time, Machined.';
  const bodyStr = roleText.body || 'Every case begins as a single billet of 904L steel.';
  const captionStr = roleText.caption || 'CALIBRE NA-01 / 72 HOUR RESERVE';

  const captionGroup = new Group();
  const padX = -plateW / 2 + 0.5;
  const baseY = -plateH / 2 + 0.5;

  // baseline rhythm 0.25
  const kicker = ctx.fontAtlas.createText(kickerStr, {
    fontSize: 40, color: '#e8ecf2', align: 'left', letterSpacingPx: 6
  });
  kicker.position.set(padX, baseY + 1.0, 0.06);
  captionGroup.add(kicker);

  const headline = ctx.fontAtlas.createText(headlineStr, {
    fontSize: 120, color: '#e8ecf2', align: 'left'
  });
  headline.position.set(padX, baseY + 0.65, 0.06);
  captionGroup.add(headline);

  // accent hairline bar 0.75w x 0.02h #ff2a38 emissive
  const barGeo = new PlaneGeometry(0.75, 0.02, 1, 1);
  const barMat = new MeshStandardNodeMaterial();
  const accCol = new Color(colors.accent);
  barMat.colorNode = vec3(accCol.r, accCol.g, accCol.b);
  barMat.emissiveNode = mul(vec3(accCol.r, accCol.g, accCol.b), float(1.8));
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(padX + 0.375, baseY + 0.42, 0.06);
  captionGroup.add(bar);
  disposables.push(barGeo, barMat);

  const body = ctx.fontAtlas.createText(bodyStr, {
    fontSize: 54, color: '#e8ecf2', align: 'left', maxWidthPx: 900
  });
  body.position.set(padX, baseY + 0.22, 0.06);
  captionGroup.add(body);

  const caption = ctx.fontAtlas.createText(captionStr, {
    fontSize: 38, color: '#e8ecf2', align: 'left', letterSpacingPx: 5
  });
  caption.position.set(padX, baseY - 0.05, 0.06);
  captionGroup.add(caption);

  group.add(captionGroup);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------
  const prims = config.cinematicPrimitives || [];
  for (const p of prims) {
    if (p && p.name && ctx.primitives[p.name]) {
      const handle = ctx.primitives[p.name](plateMesh, p.params || {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // ENTRANCE MOTION
  // ---------------------------------------------------------------
  // plate mount opacity 0 -> 1 over 500ms
  const plateTl = gsap.timeline();
  plateTl.to(uOpacity, { value: 1.0, duration: 0.5, ease: 'power2.out' });
  timelines.push(plateTl);

  // caption rise-in y +0.4 -> 0, 700ms starting 120ms after plate
  captionGroup.position.y = 0.4;
  const capTl = gsap.timeline({ delay: 0.12 });
  capTl.to(captionGroup.position, { y: 0.0, duration: 0.7, ease: 'power3.out' });
  // settle overshoot on the group scale
  captionGroup.scale.setScalar(1.04);
  capTl.to(captionGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(capTl);

  // idle breathing on plate (single slow transform)
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(plateMesh.scale, { x: 1.02, y: 1.02, duration: 4.0, ease: 'sine.inOut' });
  timelines.push(idleTl);

  // ---------------------------------------------------------------
  // SCROLL HANDLER (parallax intensity)
  // ---------------------------------------------------------------
  group.userData.handlers = {
    onScroll: (data) => {
      const p = (data && typeof data.progress === 'number') ? data.progress : 0;
      const target = (p - 0.5) * 0.35;
      gsap.to(uParallax, { value: target, duration: 0.4, ease: 'power2.out' });
    }
  };

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  group.userData.cleanup = () => {
    for (const tl of timelines) { try { tl.kill(); } catch (e) {} }
    for (const h of primitiveHandles) {
      try { if (h && h.timeline) h.timeline.kill(); } catch (e) {}
      try { if (h && h.cleanup) h.cleanup(); } catch (e) {}
    }
    for (const d of disposables) { try { d.dispose && d.dispose(); } catch (e) {} }
    try { group.traverse((o) => { if (o.geometry) o.geometry.dispose && o.geometry.dispose(); }); } catch (e) {}
  };

  return group;
}
